urlset:
{#- Zola's default sitemap, without /admin/ (#417): that page is for the
    maintainer only and stays out of search engines. #}
{%- for sitemap_entry in entries %}
{%- if not sitemap_entry.permalink is ending_with(pat="/admin/") %}

    {{ sitemap_entry.permalink | escape_xml | safe }}
    {%- if sitemap_entry.updated %}
    {{ sitemap_entry.updated }}
    {%- endif %}

{%- endif %}
{%- endfor %}
